1	// Package remediation turns a scan's findings into what can be done about
2	// them, without any I/O: which vulnerabilities have a fixed version, whether a
3	// base image or an application dependency has to move, and the command that
4	// moves it.
5	//
6	// Everything here is a function of the findings. Whether a proposed fix
7	// actually clears the CVEs is not decided here — that is measured by
8	// re-scanning, never inferred.
9	package remediation
10	
11	import (
12		"slices"
13		"sort"
14	
15		"github.com/anthnel/devdesk/internal/scan"
16	)
17	
18	// Summary counts the vulnerabilities that have a fixed version, by what has to
19	// move to clear them.
20	type Summary struct {
21		// BaseImage is fixed by a package upgrade in the image's OS (or a newer
22		// base image); Dependencies by bumping an application dependency.
23		BaseImage    int
24		Dependencies int
25		// Unclassified are fixable findings recorded without a class — a result
26		// cached before the class was stored. They are counted apart, never as
27		// either class, and disappear at the next scan.
28		Unclassified int
29		// Unfixed are vulnerabilities with no fixed version yet.
30		Unfixed int
31	}
32	
33	// Fixable is the number of vulnerabilities that have a fixed version.
34	func (s Summary) Fixable() int { return s.BaseImage + s.Dependencies + s.Unclassified }
35	
36	// Summarize counts the vulnerabilities in findings. Secrets, licenses,
37	// misconfigurations and pipeline findings are not vulnerabilities and are
38	// ignored.
39	func Summarize(findings []scan.Finding) Summary {
40		var s Summary
41		for _, f := range findings {
42			if scan.Categorize(f) != scan.CategoryVulnerability {
43				continue
44			}
45			if f.FixedIn == "" {
46				s.Unfixed++
47				continue
48			}
49			switch f.Class {
50			case scan.ClassOSPackages:
51				s.BaseImage++
52			case scan.ClassLangPackages:
53				s.Dependencies++
54			default:
55				s.Unclassified++
56			}
57		}
58		return s
59	}
60	
61	// Fix is one package that has to move, with every CVE moving it clears.
62	type Fix struct {
63		Class     string
64		Ecosystem string
65		Package   string
66		Installed string
67		// Target is the version to move to: the highest of what each CVE needs, so
68		// one bump clears them all. Empty when the versions could not be ordered;
69		// Options then lists them and none is preferred.
70		Target  string
71		Options []string
72		// Command is the command that performs the move, empty when none is known
73		// for the ecosystem or when Target is empty.
74		Command  string
75		CVEs     []string
76		Severity scan.SeverityLevel
77	}
78	
79	type fixKey struct{ ecosystem, pkg, installed string }
80	
81	// group is a Fix being built, plus what only the building needs.
82	type group struct {
83		fix Fix
84		// ambiguous is set when one CVE listed several fixed versions that
85		// scan.PickFixed could not choose between.
86		ambiguous bool
87	}
88	
89	// Group collects the fixable vulnerabilities into one Fix per (ecosystem,
90	// package, installed version), worst severity first. A package installed in
91	// two versions is two fixes: each has its own target.
92	func Group(findings []scan.Finding) []Fix {
93		byKey := map[fixKey]*group{}
94		var order []fixKey
95	
96		for _, f := range findings {
97			if scan.Categorize(f) != scan.CategoryVulnerability || f.FixedIn == "" || f.PkgName == "" {
98				continue
99			}
100			key := fixKey{f.Ecosystem, f.PkgName, f.Version}
101			g, seen := byKey[key]
102			if !seen {
103				g = &group{fix: Fix{
104					Class: f.Class, Ecosystem: f.Ecosystem, Package: f.PkgName,
105					Installed: f.Version, Severity: f.Severity,
106				}}
107				byKey[key] = g
108				order = append(order, key)
109			}
110			g.add(f)
111		}
112	
113		fixes := make([]Fix, 0, len(order))
114		for _, key := range order {
115			fixes = append(fixes, byKey[key].done())
116		}
117		sort.SliceStable(fixes, func(i, j int) bool {
118			return severityRank(fixes[i].Severity) > severityRank(fixes[j].Severity)
119		})
120		return fixes
121	}
122	
123	// add records one vulnerability: its ID, its severity, and the version it needs.
124	func (g *group) add(f scan.Finding) {
125		g.fix.CVEs = append(g.fix.CVEs, f.ID)
126		if severityRank(f.Severity) > severityRank(g.fix.Severity) {
127			g.fix.Severity = f.Severity
128		}
129		need := scan.PickFixed(f.Version, f.FixedIn)
130		if need == "" {
131			// Several fixed versions and no way to choose: keep the raw list so
132			// the reader sees it, and give up on a single target.
133			g.ambiguous = true
134			need = f.FixedIn
135		}
136		if !slices.Contains(g.fix.Options, need) {
137			g.fix.Options = append(g.fix.Options, need)
138		}
139	}
140	
141	// done settles Target and Command: the highest version any CVE needs, so one
142	// bump clears them all — provided the versions can be ordered.
143	func (g *group) done() Fix {
144		fix := g.fix
145		sort.Strings(fix.Options)
146		if !g.ambiguous {
147			fix.Target = highest(fix.Options)
148		}
149		if fix.Target != "" {
150			fix.Command, _ = scan.FixCommand(fix.Ecosystem, fix.Package, fix.Target)
151		}
152		return fix
153	}
154	
155	// highest returns the greatest of versions, or "" if two of them cannot be
156	// ordered. A lone version is returned as is, orderable or not.
157	func highest(versions []string) string {
158		best := versions[0]
159		for _, v := range versions[1:] {
160			c, ok := scan.CompareVersions(v, best)
161			if !ok {
162				return ""
163			}
164			if c > 0 {
165				best = v
166			}
167		}
168		return best
169	}
170	
171	func severityRank(s scan.SeverityLevel) int {
172		switch s {
173		case scan.SeverityCritical:
174			return 4
175		case scan.SeverityHigh:
176			return 3
177		case scan.SeverityMedium:
178			return 2
179		case scan.SeverityLow:
180			return 1
181		}
182		return 0
183	}
