1	package remediation
2	
3	import (
4		"fmt"
5		"log"
6		"os"
7		"path/filepath"
8		"strconv"
9	
10		"github.com/anthnel/devdesk/internal/dockerfile"
11	)
12	
13	// Entry is one base image of one Dockerfile, and what it could become.
14	type Entry struct {
15		// File is the Dockerfile's path relative to the repository, with forward
16		// slashes.
17		File string
18		// Stage is the FROM as parsed, with the byte range that spells the image.
19		Stage dockerfile.Stage
20		// StageLabel is what the table calls the stage: its AS name, or its position.
21		StageLabel string
22		// Image is the reference the stage resolves to, and Candidates the full
23		// references it could move to, best first. Reason says why there are none —
24		// the reference could not be resolved, has no version to move from, or is
25		// already on the newest tag of its line — and is empty when there are some.
26		Image      string
27		Candidates []string
28		Reason     string
29	}
30	
31	// TagLister returns the tags a repository holds. Discover takes it as a
32	// function so that the walk, the parsing and the tag policy can be exercised
33	// without a registry.
34	type TagLister func(Ref) ([]string, error)
35	
36	// Discover finds the Dockerfiles under root and, for each base image, the
37	// candidates the tag policy allows among the tags list returns.
38	//
39	// It never fails on one image: a registry that cannot be reached, or a
40	// reference that cannot be resolved, is that entry's Reason and the rest carry
41	// on. Only an unreadable root is an error. FROM scratch and FROM <an earlier
42	// stage> are not images and produce no entry.
43	func Discover(root string, list TagLister, track Track, max int) (entries []Entry, truncated bool, err error) {
44		files, truncated, err := dockerfile.Find(root)
45		if err != nil {
46			return nil, false, err
47		}
48	
49		tagsByRepo := map[string]tagResult{}
50		for _, rel := range files {
51			content, readErr := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
52			if readErr != nil {
53				log.Printf("ERROR [remediation] read %s: %v", rel, readErr)
54				continue
55			}
56			for i, stage := range dockerfile.Parse(content).Stages {
57				if stage.Kind != dockerfile.KindImage {
58					continue
59				}
60				entry := Entry{File: rel, Stage: stage, StageLabel: stageLabel(stage, i), Image: stage.Image}
61				if stage.Unresolved != "" {
62					entry.Reason = stage.Unresolved
63				} else {
64					entry.Candidates, entry.Reason = candidatesFor(ParseRef(stage.Image), list, tagsByRepo, track, max)
65				}
66				entries = append(entries, entry)
67			}
68		}
69		return entries, truncated, nil
70	}
71	
72	func stageLabel(stage dockerfile.Stage, index int) string {
73		if stage.Name != "" {
74			return stage.Name
75		}
76		return "#" + strconv.Itoa(index+1)
77	}
78	
79	type tagResult struct {
80		tags []string
81		err  error
82	}
83	
84	// candidatesFor lists a repository's tags once per run — several stages, and
85	// several Dockerfiles, share a base — and applies the policy.
86	func candidatesFor(ref Ref, list TagLister, seen map[string]tagResult, track Track, max int) ([]string, string) {
87		// A tag with no version to move from is refused before any request: the
88		// answer does not depend on what the registry holds.
89		if version, _ := SplitTag(ref.Tag); ref.Tag == "" || version == "" {
90			_, reason := Candidates(ref.Tag, nil, track, max)
91			return nil, reason
92		}
93	
94		key := ref.Registry + "/" + ref.Repository
95		res, ok := seen[key]
96		if !ok {
97			res.tags, res.err = list(ref)
98			seen[key] = res
99		}
100		if res.err != nil {
101			log.Printf("ERROR [remediation] list tags of %s: %v", key, res.err)
102			return nil, fmt.Sprintf("could not list tags of %s — check logs", ref.Name)
103		}
104	
105		tags, reason := Candidates(ref.Tag, res.tags, track, max)
106		out := make([]string, 0, len(tags))
107		for _, t := range tags {
108			out = append(out, ref.WithTag(t))
109		}
110		return out, reason
111	}
