1	// Package dockerfile reads the base images a Dockerfile builds on, and where in
2	// the file each one is written.
3	//
4	// It exists for the security remediation (§3.2): a scan says which packages are
5	// vulnerable, and the Dockerfile is where the base image that carries them is
6	// named. Every image it reports comes with the byte range that spells it, so a
7	// later edit replaces those bytes and nothing else — comments, line endings and
8	// the rest of the file are never re-serialized.
9	//
10	// It is a reader, not a validator. It does not run the instructions, does not
11	// know about --build-arg overrides, and a Dockerfile it cannot make sense of
12	// yields fewer stages rather than an error.
13	package dockerfile
14	
15	import (
16		"regexp"
17		"strings"
18	
19		"github.com/anthnel/devdesk/internal/patch"
20	)
21	
22	// Span is patch.Span: a range of bytes, End exclusive. It is spelled here as
23	// well so a reader of this file does not have to go looking, and because every
24	// span this parser produces exists to be handed to patch.Rewrite.
25	type Span = patch.Span
26	
27	// Kind says what a FROM instruction names.
28	type Kind int
29	
30	const (
31		// KindImage is an image reference, resolved or not.
32		KindImage Kind = iota
33		// KindScratch is `FROM scratch`: the empty image, nothing to scan or bump.
34		KindScratch
35		// KindStage is a FROM that names an earlier stage of the same file.
36		KindStage
37	)
38	
39	// Stage is one FROM instruction.
40	type Stage struct {
41		// Line is the 1-based line of the FROM keyword.
42		Line int
43		// Name is the `AS name` of the stage, empty if it has none.
44		Name string
45		// Platform is the --platform flag as written (possibly a variable).
46		Platform string
47		Kind     Kind
48		// Written is the image token exactly as it appears after FROM, so a view
49		// can show `${BASE}` next to what it resolves to.
50		Written string
51		// Image is the reference once build args are substituted. Empty for a
52		// scratch or stage FROM, and when Unresolved says why it could not be.
53		Image      string
54		Unresolved string
55		// Span is where the image is spelled, and Editable says whether replacing
56		// those bytes changes this stage's image. When the reference comes from an
57		// ARG default, Span is that default's value in the ARG line: the one place
58		// the image is actually written. Several stages can share it.
59		Span         Span
60		Editable     bool
61		NoEditReason string
62	}
63	
64	// File is a parsed Dockerfile.
65	type File struct {
66		Stages []Stage
67	}
68	
69	// argValue is a global ARG (declared before the first FROM) and where its
70	// default is written.
71	type argValue struct {
72		value      string
73		hasDefault bool
74		span       Span
75	}
76	
77	type line struct {
78		off  int
79		text string
80	}
81	
82	type piece struct {
83		off  int
84		text string
85	}
86	
87	type token struct {
88		span Span
89		text string
90	}
91	
92	var directive = regexp.MustCompile(`^#\s*([A-Za-z]+)\s*=\s*(\S+)\s*$`)
93	
94	// Parse reads the FROM instructions of a Dockerfile.
95	func Parse(content []byte) File {
96		lines := splitLines(content)
97		esc := escapeChar(lines)
98	
99		var file File
100		args := map[string]argValue{}
101		names := map[string]bool{}
102		inStage := false
103	
104		for i := 0; i < len(lines); {
105			trimmed := strings.TrimSpace(lines[i].text)
106			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
107				i++
108				continue
109			}
110			first := i
111			pieces, next := gather(lines, i, esc)
112			i = next
113			tokens := tokenize(pieces)
114			if len(tokens) == 0 {
115				continue
116			}
117			switch strings.ToUpper(tokens[0].text) {
118			case "ARG":
119				if !inStage {
120					readArgs(tokens[1:], args)
121				}
122			case "FROM":
123				stage := readFrom(tokens[1:], args, names)
124				stage.Line = first + 1
125				file.Stages = append(file.Stages, stage)
126				if stage.Name != "" {
127					names[strings.ToLower(stage.Name)] = true
128				}
129				inStage = true
130			}
131		}
132		return file
133	}
134	
135	// splitLines cuts content into physical lines, keeping each one's byte offset.
136	// A trailing \r is dropped from the text but the offsets stay absolute.
137	func splitLines(b []byte) []line {
138		var lines []line
139		start := 0
140		for i := 0; i <= len(b); i++ {
141			if i < len(b) && b[i] != '\n' {
142				continue
143			}
144			if i == len(b) && start == len(b) {
145				break
146			}
147			text := string(b[start:i])
148			text = strings.TrimSuffix(text, "\r")
149			lines = append(lines, line{off: start, text: text})
150			start = i + 1
151		}
152		return lines
153	}
154	
155	// escapeChar reads the `# escape=` parser directive, which only counts at the
156	// very top of the file.
157	func escapeChar(lines []line) byte {
158		for _, l := range lines {
159			m := directive.FindStringSubmatch(strings.TrimSpace(l.text))
160			if m == nil {
161				break
162			}
163			if strings.EqualFold(m[1], "escape") && len(m[2]) == 1 && (m[2] == "`" || m[2] == `\`) {
164				return m[2][0]
165			}
166		}
167		return '\\'
168	}
169	
170	// gather collects the physical lines of the instruction starting at lines[i],
171	// following the escape character across line breaks. Comment and blank lines
172	// inside a continuation are skipped, as Docker does.
173	func gather(lines []line, i int, esc byte) (pieces []piece, next int) {
174		for i < len(lines) {
175			text := strings.TrimRight(lines[i].text, " \t")
176			if text == "" || text[len(text)-1] != esc {
177				pieces = append(pieces, piece{off: lines[i].off, text: lines[i].text})
178				return pieces, i + 1
179			}
180			pieces = append(pieces, piece{off: lines[i].off, text: text[:len(text)-1]})
181			i++
182			for i < len(lines) {
183				t := strings.TrimSpace(lines[i].text)
184				if t != "" && !strings.HasPrefix(t, "#") {
185					break
186				}
187				i++
188			}
189		}
190		return pieces, i
191	}
192	
193	// tokenize splits pieces on spaces and tabs, with absolute byte spans.
194	func tokenize(pieces []piece) []token {
195		var tokens []token
196		for _, p := range pieces {
197			start := -1
198			for j := 0; j <= len(p.text); j++ {
199				space := j == len(p.text) || p.text[j] == ' ' || p.text[j] == '\t'
200				switch {
201				case !space && start < 0:
202					start = j
203				case space && start >= 0:
204					tokens = append(tokens, token{
205						span: Span{Start: p.off + start, End: p.off + j},
206						text: p.text[start:j],
207					})
208					start = -1
209				}
210			}
211		}
212		return tokens
213	}
214	
215	// readArgs records `ARG NAME[=default] ...` into args. A later declaration of
216	// the same name replaces the earlier one, as it does for a following FROM.
217	func readArgs(tokens []token, args map[string]argValue) {
218		for _, t := range tokens {
219			name, value, hasDefault := strings.Cut(t.text, "=")
220			if name == "" {
221				continue
222			}
223			a := argValue{}
224			if hasDefault {
225				start := t.span.Start + len(name) + 1
226				end := t.span.End
227				if len(value) >= 2 && (value[0] == '"' || value[0] == '\'') && value[len(value)-1] == value[0] {
228					value = value[1 : len(value)-1]
229					start++
230					end--
231				}
232				a = argValue{value: value, hasDefault: true, span: Span{Start: start, End: end}}
233			}
234			args[name] = a
235		}
236	}
237	
238	// readFrom reads what follows the FROM keyword: flags, the image, `AS name`.
239	func readFrom(tokens []token, args map[string]argValue, names map[string]bool) Stage {
240		var st Stage
241		i := 0
242		for i < len(tokens) && strings.HasPrefix(tokens[i].text, "--") {
243			if k, v, ok := strings.Cut(tokens[i].text, "="); ok && strings.EqualFold(k, "--platform") {
244				st.Platform = v
245			}
246			i++
247		}
248		if i >= len(tokens) {
249			st.Unresolved = "FROM names no image"
250			return st
251		}
252		image := tokens[i]
253		if i+2 < len(tokens) && strings.EqualFold(tokens[i+1].text, "AS") {
254			st.Name = tokens[i+2].text
255		}
256		st.Written = image.text
257	
258		switch {
259		case strings.EqualFold(image.text, "scratch"):
260			st.Kind = KindScratch
261		case names[strings.ToLower(image.text)]:
262			st.Kind = KindStage
263		default:
264			resolveImage(&st, image, args)
265		}
266		return st
267	}
268	
269	// resolveImage fills in Image, Span and Editable for an image token.
270	func resolveImage(st *Stage, image token, args map[string]argValue) {
271		resolved, ok, sole := expand(image.text, args)
272		if !ok {
273			st.Unresolved = "the reference uses a build arg with no default"
274			return
275		}
276		st.Image = resolved
277		if !strings.Contains(image.text, "$") {
278			st.Span, st.Editable = image.span, true
279			return
280		}
281		if sole != nil && sole.hasDefault {
282			// The whole reference is one variable: the default in its ARG line is
283			// where the image is written. A --build-arg on the command line can
284			// still override it, which a file cannot show.
285			st.Span, st.Editable = sole.span, true
286			return
287		}
288		st.NoEditReason = "the reference is assembled from build args, so no single place in the file spells it"
289	}
290	
291	var reference = regexp.MustCompile(`\$(?:\{([A-Za-z_][A-Za-z0-9_]*)(?:(:?-)([^}]*))?\}|([A-Za-z_][A-Za-z0-9_]*))`)
292	
293	// expand substitutes ${NAME}, $NAME, ${NAME:-default} and ${NAME-default}
294	// from the global ARGs. ok is false when a variable has no value; sole is the
295	// ARG when s is nothing but one reference to it.
296	func expand(s string, args map[string]argValue) (out string, ok bool, sole *argValue) {
297		ok = true
298		whole := reference.FindStringSubmatchIndex(s)
299		out = reference.ReplaceAllStringFunc(s, func(m string) string {
300			sub := reference.FindStringSubmatch(m)
301			name := sub[1]
302			if name == "" {
303				name = sub[4]
304			}
305			a, declared := args[name]
306			switch {
307			case declared && a.hasDefault && (a.value != "" || sub[2] != ":-"):
308				return a.value
309			case sub[2] != "":
310				return sub[3]
311			}
312			ok = false
313			return m
314		})
315		if whole != nil && whole[0] == 0 && whole[1] == len(s) {
316			sub := reference.FindStringSubmatch(s)
317			name := sub[1]
318			if name == "" {
319				name = sub[4]
320			}
321			if a, declared := args[name]; declared {
322				sole = &a
323			}
324		}
325		return out, ok, sole
326	}
