1	package patch
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// ErrChanged is returned by WriteIfUnchanged when the file no longer holds what
12	// the edit was computed from.
13	var ErrChanged = errors.New("the file changed since it was read")
14	
15	// WriteIfUnchanged replaces the file at path with updated, provided it still
16	// holds exactly expected — the content the change was computed from, and the one
17	// the user was shown and agreed to. Anything else is ErrChanged and the file is
18	// left alone: the user confirmed *that* diff, not another.
19	//
20	// The write goes through a temporary file in the same directory, then a rename,
21	// so a reader never sees half a file and a failure leaves the original in
22	// place. The file's permission bits are kept; a symbolic link is followed and
23	// its target replaced, not the link. The owner is not preserved when the process
24	// cannot chown, which is the ordinary case.
25	func WriteIfUnchanged(path string, expected, updated []byte) error {
26		target, err := filepath.EvalSymlinks(path)
27		if err != nil {
28			return err
29		}
30		current, err := os.ReadFile(target)
31		if err != nil {
32			return err
33		}
34		if !bytes.Equal(current, expected) {
35			return ErrChanged
36		}
37		info, err := os.Stat(target)
38		if err != nil {
39			return err
40		}
41	
42		tmp, err := os.CreateTemp(filepath.Dir(target), filepath.Base(target)+".devdesk-*")
43		if err != nil {
44			return err
45		}
46		name := tmp.Name()
47		fail := func(err error) error {
48			_ = tmp.Close()
49			_ = os.Remove(name)
50			return err
51		}
52		if _, err := tmp.Write(updated); err != nil {
53			return fail(fmt.Errorf("write %s: %w", name, err))
54		}
55		if err := tmp.Chmod(info.Mode().Perm()); err != nil {
56			return fail(err)
57		}
58		if err := tmp.Close(); err != nil {
59			_ = os.Remove(name)
60			return err
61		}
62		if err := os.Rename(name, target); err != nil {
63			_ = os.Remove(name)
64			return err
65		}
66		return nil
67	}
